/* Database CheckCommands. Thresholds come from service vars; the plugin defaults apply
 * only when a service sets none. */

object CheckCommand "mysql-repl-lag" {
  command = [ PluginContribDir + "/rhdp/check_repl_lag.py" ]
  arguments = {
    "--warning"  = { value = "$repl_lag_warn$"; set_if = {{ macro("$repl_lag_warn$") != "" }} }
    "--critical" = { value = "$repl_lag_crit$"; set_if = {{ macro("$repl_lag_crit$") != "" }} }
  }
}

object CheckCommand "mysql-threads" {
  command = [ PluginContribDir + "/rhdp/check_threads.py" ]
  arguments = {
    "--warning"  = "$threads_warn$"
    "--critical" = "$threads_crit$"
  }
  vars.threads_warn = 64
  vars.threads_crit = 128
}
